solution.solution.js:
function line(label, cents) {
  const shown = label.length > 19 ? label.slice(0, 18) + "…" : label;
  return shown.padEnd(19) + (cents / 100).toFixed(2).padStart(8);
}

function formatReceipt(items, tipPercent) {
  const lines = [];
  let subtotal = 0;
  for (const item of items) {
    if (item.qty <= 0) continue;
    const cents = Math.round(item.price * 100) * item.qty;
    subtotal += cents;
    lines.push(line(item.qty > 1 ? `${item.name} x${item.qty}` : item.name, cents));
  }
  if (lines.length === 0) return "No items";
  const tip = Math.round(subtotal * tipPercent / 100);
  lines.push("-".repeat(27));
  lines.push(line("Subtotal", subtotal));
  if (tipPercent !== 0) lines.push(line(`Tip ${tipPercent}%`, tip));
  lines.push(line("Total", subtotal + tip));
  return lines.join("\n");
}

unitTests:
test("the example", () => {
  checkEq(formatReceipt([{ name: "Green tea", price: 2.5, qty: 2 }, { name: "Chocolate cake", price: 4.25, qty: 1 }], 10),
    "Green tea x2           5.00\nChocolate cake         4.25\n---------------------------\nSubtotal               9.25\nTip 10%                0.93\nTotal                 10.18");
});

test("no tip", () => {
  checkEq(formatReceipt([{ name: "Mug", price: 8, qty: 1 }], 0),
    "Mug                    8.00\n---------------------------\nSubtotal               8.00\nTotal                  8.00");
});

test("cents stay exact", () => {
  const r = formatReceipt([{ name: "Sweet", price: 0.1, qty: 3 }, { name: "Gum", price: 0.2, qty: 1 }], 0);
  check(r.endsWith("Total                  0.50"), r);
});

test("long names and skipped items", () => {
  checkEq(formatReceipt([{ name: "An extraordinarily long name", price: 1, qty: 1 }, { name: "Ghost", price: 5, qty: 0 }], 0).split("\n")[0],
    "An extraordinarily…    1.00");
  checkEq(formatReceipt([{ name: "Ghost", price: 5, qty: 0 }], 15), "No items");
  checkEq(formatReceipt([], 15), "No items");
});

test("a large order", () => {
  const r = formatReceipt([{ name: "Laptop", price: 1299.99, qty: 3 }], 12.5).split("\n");
  checkEq(r[0], "Laptop x3           3899.97");
  checkEq(r.at(-2), "Tip 12.5%            487.50");
  checkEq(r.at(-1), "Total               4387.47");
});

